// Formatted and commented 10/2023

document.addEventListener("turbolinks:load", function () {
  $("#user_light_mode").on("change", function () {
    if ($(this).val() == "Classic") {
      $("body").removeClass("theme-modern");
      $("body").removeClass("theme-modern-dark");
    } else if ($(this).val() == "Modern Dark") {
      $("body").removeClass("theme-modern");
      $("body").addClass("theme-modern-dark");
    } else {
      $("body").removeClass("theme-modern-dark");
      $("body").addClass("theme-modern");
    }
  });

  $("#user_accent").on("change", function () {
    if ($(this).val() == "Blue") {
      $("body").removeClass("red");
      $("body").removeClass("green");
      $("body").removeClass("purple");
      $("body").addClass("blue");
    } else if ($(this).val() == "Red") {
      $("body").removeClass("blue");
      $("body").removeClass("green");
      $("body").removeClass("purple");
      $("body").addClass("red");
    } else if ($(this).val() == "Green") {
      $("body").removeClass("blue");
      $("body").removeClass("purple");
      $("body").removeClass("red");
      $("body").addClass("green");
    } else if ($(this).val() == "Purple") {
      $("body").removeClass("blue");
      $("body").removeClass("red");
      $("body").removeClass("green");
      $("body").addClass("purple");
    }
  });

  $("#user_font_sizing").on("change", function () {
    if ($(this).val() == "12px") {
      $("html").css("font-size", "12px");
    } else if ($(this).val() == "16px") {
      $("html").css("font-size", "16px");
    } else if ($(this).val() == "20px") {
      $("html").css("font-size", "20px");
    } else if ($(this).val() == "24px") {
      $("html").css("font-size", "24px");
    }
  });
});
// Formatted and commented 10/2023

document.addEventListener("turbolinks:load", function () {
  var isMobile = window.matchMedia("only screen and (max-width: 991px)");

  if (isMobile.matches) {
    // set hanko style based on completeness
    $(".lesson-tile").each(function () {
      var holder = $("#lesson5-" + $(this).attr("id"));
      var grammarTileCount = holder.find(".grammar-tile").length;
      var completeTileCount = holder.find(".tile--review-complete").length;
      var incompleteTileCount = holder.find(".incomplete-grammar").length;

      if (grammarTileCount == completeTileCount + incompleteTileCount && grammarTileCount > 0) {
        $(this).addClass("tile--review-complete");
      } else if (grammarTileCount == 0) {
        $(this).addClass("lesson--in-development");
      };
    });

    // set hanko style based on completeness
    $(".jlpt-level-tile").each(function () {
      var head = $("#" + $(this).find($(".jlpt-level-tile__english")).html());
      headCompleteCount = head.find(".tile--review-complete").length;

      if (headCompleteCount == 10) {
        $(this).addClass("tile--review-complete");
      };
    });

    // shows the lesson group based on level tile
    function showLevel(element) {
      var id = $(element).find($(".jlpt-level-tile__english")).html();
      $("#" + id).show();

      if (typeof Storage !== "undefined") {
        sessionStorage.setItem("levelToShow", id);
      };
    };

    // shows the gp tile group based on lesson tile
    function showLesson(element) {
      var lesson_id = $(element).attr("id");
      $("#lesson5-" + lesson_id).show();

      if (typeof Storage !== "undefined") {
        sessionStorage.setItem("lessonToShow", lesson_id);
      };
    };

    // shows tiles based on session storage
    function fillPage() {
      var level = $("." + sessionStorage.getItem("levelToShow"));

      if (isMobile.matches) {
        $(".lesson-tile-holder").detach().insertAfter(level);
      };

      level.addClass("tile--highlight");
      showLevel(level);

      if (sessionStorage.getItem("lessonToShow")) {
        var lesson = $("#" + sessionStorage.getItem("lessonToShow"));
        lesson.addClass("tile--highlight");

        if (isMobile.matches) {
          $(".grammar-holder").detach().insertAfter(lesson);
        };

        showLesson(lesson);
      };
    };

    // fills page on page load
    if ($("#lessons").length >= 1 && typeof Storage !== "undefined" && sessionStorage.getItem("levelToShow")) {
      fillPage();
    };

    // lesson tile click handler
    $("#lessons .lesson-tile").on("click", function (event) {
      $(".lesson-tile").removeClass("tile--highlight");
      $(this).addClass("tile--highlight");

      if ($(this).next().hasClass("grammar-holder")) {
        $(this).next().show();
      } else {
        if (isMobile.matches) {
          $("#lesson5-" + $(this).attr("id")).detach().insertAfter($(this));
        };

        showLesson($(this));
      };
    });

    // level tile click handler
    $("#lessons .jlpt-level-tile").on("click", function (event) {
      sessionStorage.clear();
      $(".jlpt-level-tile").removeClass("tile--highlight");
      $(".lesson-tile").removeClass("tile--highlight");
      $(this).addClass("tile--highlight");

      if ($(this).next().hasClass("lesson-tile-holder")) {
        $(this).next().show();
      } else {
        if (isMobile.matches) {
          $("#" + $(this).find($(".jlpt-level-tile__english")).html()).detach().insertAfter($(this));
        } else {
          showLevel($(this));
        };
      };
    });

    // touch actions
    if ($("#lessons").length >= 1 || $(".js_search-container_query").length >= 1) {
      var dragging = false;

      $("body").on("touchmove", function () {
        dragging = true;
      });

      $("body").on("touchstart", function () {
        dragging = false;
      });

      $("#lessons .grammar-tile").on("touchend", function (e) {
        if (dragging) {
          return;
        }

        window.open($($(this).find("a")[0]).attr("href"), "_blank");
        return false;
      });

      $(".grammar-holder .grammar-tile").on("touchend", function (e) {
        if (dragging) {
          return;
        }

        if ($(".js_search-button_select.active").length == 0 || $(".add-selected-grammar.active").length == 0) {
          window.open($($(this).find("a")[0]).attr("href"), "_blank");
          return false;
        };
      });

      $("#lessons .lesson-tile").on("touchend", function (e) {
        if (dragging) {
          return;
        }

        $(this).click();
      });

      $("#lessons .jlpt-level-tile").on("touchend", function (e) {
        if (dragging) {
          return;
        }
        $(this).click();
      });
    };
  } else {
    $(".lesson-tile").each(function () {
      var holder = $("#lesson5-" + $(this).attr("id"));
      var holderTileCount = holder.find(".grammar-tile").length;
      var holderIncompleteCount = holder.find(".incomplete-grammar").length;
      var holderBurnedCount = holder.find(".tile--review-complete--burned").length;
      var holderCompleteCount = holder.find(".tile--review-complete").length;

      if (holderTileCount == holderIncompleteCount + holderBurnedCount && holderTileCount > 0) {
        $(this).addClass("tile--review-complete--burned");
      } else if (holderTileCount == holderCompleteCount + holderIncompleteCount && holderTileCount > 0) {
        $(this).addClass("tile--review-complete");
      } else if (holderTileCount == 0) {
        $(this).addClass("lesson--in-development");
      };
    });

    $(".jlpt-level-tile").each(function () {
      var head = $("#" + $(this).find($(".jlpt-level-tile__english")).html());
      var headBurnedCount = head.find(".tile--review-complete--burned").length;
      var headCompleteCount = head.find(".tile--review-complete").length;

      if (headBurnedCount == 10) {
        $(this).addClass("tile--review-complete--burned");
      } else if (headCompleteCount + headBurnedCount == 10) {
        $(this).addClass("tile--review-complete");
      };
    });

    function showLevel(element) {
      var id = $(element).find($(".jlpt-level-tile__english")).html();
      $(".lesson-tile-holder").hide();
      $(".grammar-holder").hide();
      $("#" + id).show();

      if (typeof Storage !== "undefined") {
        sessionStorage.setItem("levelToShow", id);
      };
    };

    function showLesson(element) {
      var lesson_id = $(element).attr("id");
      $("#lesson5-" + lesson_id).show();

      if (typeof Storage !== "undefined") {
        sessionStorage.setItem("lessonToShow", lesson_id);
      };
    };

    function fillPage() {
      var level = $("." + sessionStorage.getItem("levelToShow"));

      if (isMobile.matches) {
        $(".lesson-tile-holder").detach().insertAfter(level);
      };

      level.addClass("tile--highlight");
      showLevel(level);

      if (sessionStorage.getItem("lessonToShow")) {
        var lesson = $("#" + sessionStorage.getItem("lessonToShow"));
        lesson.addClass("tile--highlight");

        if (isMobile.matches) {
          $(".grammar-holder").detach().insertAfter(lesson);
          $("body").scrollTop(lesson.offset().top - $("nav").height());
        };

        showLesson(lesson);
      };
    };

    $(".lesson-tile").on("click", function (event) {
      $(".lesson-tile").removeClass("tile--highlight");
      $(this).addClass("tile--highlight");
      $(".grammar-holder").hide();

      if ($(this).next().hasClass("grammar-holder")) {
        $(".grammar-holder").toggle();
      } else {
        if (isMobile.matches) {
          $("#lesson5-" + $(this).attr("id")).detach().insertAfter($(this));
          $("body").scrollTop($(this).offset().top - $("nav").height());
        };

        showLesson($(this));
      };
    });

    $(".jlpt-level-tile").on("click", function (event) {
      sessionStorage.clear();
      $(".jlpt-level-tile").removeClass("tile--highlight");
      $(".lesson-tile").removeClass("tile--highlight");
      $(this).addClass("tile--highlight");

      if ($(this).next().hasClass("lesson-tile-holder")) {
        $(this).next().toggle();
      } else {
        if (isMobile.matches) {
          $("#" + $(this).find($(".jlpt-level-tile__english")).html()).detach().insertAfter($(this));
          $("body").scrollTop($(this).offset().top - $("nav").height());
        } else {
          showLevel($(this));
        };
      };
    });
  };
});
