(function ($) {
  $.fn.JVFurigana = function (options) {
    var vocab = {};
    function getKnownKanji() {
      return $.ajax({
        type: "GET",
        async: false,
        url: "/user_furigana",
        dataType: "json",
      });
    }

    if (typeof localStorage !== "undefined") {
      try {
        localStorage.setItem("feature_test", "yes");

        if (localStorage.getItem("feature_test") === "yes") {
          localStorage.removeItem("feature_test");

          if (
            localStorage.getItem("vocab") &&
            JSON.parse(localStorage.getItem("vocab"))["data"] != null &&
            JSON.stringify(JSON.parse(localStorage.getItem("vocab"))["data"]) !=
              "{}"
          ) {
            var now = new Date().getTime();

            if (
              JSON.parse(localStorage.getItem("vocab"))["timestamp"] == null ||
              JSON.parse(localStorage.getItem("vocab"))["timestamp"] <
                now - 43200000 ||
              JSON.parse(localStorage.getItem("vocab"))["timestamp"] <
                1521067292311
            ) {
              getKnownKanji().done(function (data) {
                vocab = data;
                var vocab_data = {
                  data: data,
                  timestamp: new Date().getTime(),
                };
                localStorage.setItem("vocab", JSON.stringify(vocab_data));
              });
            } else {
              vocab = JSON.parse(localStorage.getItem("vocab"))["data"];
            }
          }
        }
      } catch (e) {
        console.error(
          "You need to enable cookies to access custom furigana settings"
        );
      }
    } else {
      console.error(
        "You need to enable cookies to access custom furigana settings"
      );
    }

    if (vocab == {}) {
      this.defaultOptions = {
        html: true, // When set to true this will use jQuery's .html() function to get the contents
        // of the passed selectors. Otherwise it will use .text(), therefore losing all
        // styling.

        forceRender: false, // Will force rendering in non supported browsers. This usually results in no visible
        // change in the output though results may vary depending on the browser.
      };

      var settings = $.extend({}, this.defaultOptions, options),
        patt = XRegExp(
          "([\\p{Han}]*)" + "（([\\p{Hiragana}|\\p{Katakana}]*)）",
          "gim"
        );

      return this.each(function () {
        //if ($.browser.mozilla || $.browser.opera) {
        // Incompatible browser detected
        //     if (!settings.forceRender) {
        //   return;
        //    }
        //}

        var $this = $(this),
          text = "";

        if (settings.html) {
          text = $this.html();
        } else {
          text = $this.text();
        }

        text = text.replace(
          patt,
          "<ruby>$1<rp>（</rp><rt>$2</rt><rp>）</rp></ruby>"
        );

        $this.html(text);
      });
    } else {
      this.defaultOptions = {
        html: true, // When set to true this will use jQuery's .html() function to get the contents
        // of the passed selectors. Otherwise it will use .text(), therefore losing all
        // styling.

        forceRender: false, // Will force rendering in non supported browsers. This usually results in no visible
        // change in the output though results may vary depending on the browser.
      };

      var settings = $.extend({}, this.defaultOptions, options),
        patt = XRegExp(
          "([\\p{Han}]+[\\p{Hiragana}|\\p{Katakana}]*)" +
            "（([\\p{Hiragana}|\\p{Katakana}]*)）",
          "gim"
        );

      return this.each(function () {
        //if ($.browser.mozilla || $.browser.opera) {
        // Incompatible browser detected
        //     if (!settings.forceRender) {
        //   return;
        //    }
        //}

        var $this = $(this),
          text = "";

        if (settings.html) {
          text = $this.html();
        } else {
          text = $this.text();
        }

        text = text.replace(patt, function (match, p1, p2) {
          var truth = true;
          for (var i = 0; i < p1.length; i++) {
            if (Object.keys(vocab).indexOf(p1[i]) > -1) {
            } else {
              truth = false;
            }
          }
          if (truth) {
            return (
              "<ruby>" +
              p1 +
              "<rp>（</rp><rt class='hide-furigana'>" +
              p2 +
              "</rt><rp>）</rp></ruby>"
            );
          } else {
            return (
              "<ruby>" + p1 + "<rp>（</rp><rt>" + p2 + "</rt><rp>）</rp></ruby>"
            );
          }
        });
        $this.html(text);
      });
    }
  };
})(jQuery);

