document.addEventListener("turbolinks:load", function () {
  if ($(".js_admin-wrapper_furigana").length >= 1) {
    $(".js_admin-wrapper_furigana").JVFurigana();
  }
  $("#new-wrapper-form").on("submit", function () {
    $(this).find(".loading-spinner").show();
  });
  if ($(".admin-set_user_field_form").length >= 1) {
    $(".admin-set_user_field_form select").on("change", function (e) {
      $(this).closest("form").submit();
    });
  }
  if ($(".admin_edit_page").length >= 1) {
    $(".js-admin-i18n-btn").on("click", function (e) {
      $(".js-admin-i18n-btn").removeClass("active");
      $(this).addClass("active");
      $(".admin-form-item").removeClass("active");
      $(".js-admin-i18n-form--" + $(this).data("lang")).addClass("active");
    });
  }
  if ($("#vocabCoverageTab").length >= 1) {
    console.log("test6")
    const container = document.querySelector(".gp-vocab-coverage");
    if (!container || container.dataset.initialized) { return; }
      container.dataset.initialized = "true";

      const hiddenInput = container.querySelector('[data-role="coverage-hidden"]');
      const pillsHolder = container.querySelector('.js-coverage-pills');
      const addTokenInput = container.querySelector('.js-add-token-input');
      const addTokenButton = container.querySelector('.js-add-token-button');
      const addSearchInput = container.querySelector('.js-add-search-input');
      const addSearchResults = container.querySelector('.js-add-search-results');
      const replacePanel = container.querySelector('.gp-vocab-coverage__replace');
      const replaceInfo = container.querySelector('.js-replace-info');
      const replaceSearchInput = container.querySelector('.js-replace-search-input');
      const replaceSearchResults = container.querySelector('.js-replace-search-results');
      const replaceCancel = container.querySelector('.js-replace-cancel');

      const vocabMeta = (() => {
        try { return JSON.parse(container.dataset.vocabMap || '{}'); }
        catch { return {}; }
    })();

    let coverageValues = (() => {
      try {
        return JSON.parse(hiddenInput.value || '[]').map((value) => {
          return isNaN(value) ? value : Number(value); // Convert numeric strings to integers
        });
      } catch {
        return [];
      }
    })();

    var replaceIndex = null;
    var addSearchTimeout = null;
    var replaceSearchTimeout = null;
    const searchUrl = container.dataset.searchUrl || '/admin/vocab_coverage_search';
    const csrfToken = document.querySelector('meta[name="csrf-token"]')?.content;

    const syncHiddenInput = () => {
      hiddenInput.value = JSON.stringify(coverageValues);
    };

    const labelForValue = (value) => {
      if (typeof value === 'number') {
        const meta = vocabMeta[String(value)];
        if (meta && meta.label) { return meta.label; }
        return `Missing vocab #${value} test`;
      }
      return value;
    };

    const tooltipForValue = (value) => {
      if (typeof value === 'number') {
        const meta = vocabMeta[String(value)];
        if (meta && meta.tooltip) { return meta.tooltip; }
        return '';
      }
      return 'Unresolved token';
    };

    const refreshReplaceState = () => {
      if (replaceIndex === null) { return; }
      if (replaceIndex < 0 || replaceIndex >= coverageValues.length) {
        exitReplaceMode();
        return;
      }
      replaceInfo.textContent = `Replacing entry #${replaceIndex + 1}: ${labelForValue(coverageValues[replaceIndex])}`;
    };

    const setReplaceMode = (index) => {
      replaceIndex = index;
      replacePanel.hidden = false;
      replaceSearchInput.value = '';
      replaceSearchResults.innerHTML = '';
      refreshReplaceState();
      replaceSearchInput.focus();
    };

    const exitReplaceMode = () => {
      replaceIndex = null;
      replacePanel.hidden = true;
      replaceInfo.textContent = 'Replace selection';
      replaceSearchInput.value = '';
      replaceSearchResults.innerHTML = '';
    };

    // --- Drag-and-drop state ---
    var dragFromIndex = null;

    const renderPills = () => {
      pillsHolder.innerHTML = '';
      if (!coverageValues.length) {
        const empty = document.createElement('p');
        empty.className = 'text-muted mb-0';
        empty.textContent = 'No vocab selected yet.';
        pillsHolder.appendChild(empty);
        return;
      }

      coverageValues.forEach((value, index) => {
        const isUnresolved = typeof value === 'string';
        const pill = document.createElement('span');
        pill.className = 'p-2 d-flex align-items-center mr-2 mb-2 u-bg_bg-tertiary u-rounded';
        pill.style.cursor = 'grab';
        pill.style.border = isUnresolved ? '2px solid #dc3545' : '2px solid transparent';
        pill.draggable = true;
        pill.dataset.index = index;
        if (replaceIndex === index) {
          pill.style.outline = '1px dashed var(--bs-primary, #0d6efd)';
          pill.style.outlineOffset = '2px';
        }
        pill.title = tooltipForValue(value);

        // Drag-and-drop handlers
        pill.addEventListener('dragstart', (e) => {
          dragFromIndex = index;
          pill.style.opacity = '0.4';
          e.dataTransfer.effectAllowed = 'move';
          e.dataTransfer.setData('text/plain', String(index));
        });
        pill.addEventListener('dragend', () => {
          pill.style.opacity = '';
          dragFromIndex = null;
          // Remove any lingering drag-over outlines
          pillsHolder.querySelectorAll('[data-index]').forEach((el) => {
            el.style.borderLeft = '';
            el.style.borderRight = '';
          });
        });
        pill.addEventListener('dragover', (e) => {
          e.preventDefault();
          e.dataTransfer.dropEffect = 'move';
          // Visual indicator of drop position
          const rect = pill.getBoundingClientRect();
          const midX = rect.left + rect.width / 2;
          if (e.clientX < midX) {
            pill.style.borderLeft = '3px solid var(--bs-primary, #0d6efd)';
            pill.style.borderRight = '';
          } else {
            pill.style.borderRight = '3px solid var(--bs-primary, #0d6efd)';
            pill.style.borderLeft = '';
          }
        });
        pill.addEventListener('dragleave', () => {
          pill.style.borderLeft = '';
          pill.style.borderRight = '';
        });
        pill.addEventListener('drop', (e) => {
          e.preventDefault();
          pill.style.borderLeft = '';
          pill.style.borderRight = '';
          const fromIdx = dragFromIndex;
          if (fromIdx === null || fromIdx === index) { return; }
          // Determine insert position based on cursor
          const rect = pill.getBoundingClientRect();
          const midX = rect.left + rect.width / 2;
          let toIdx = e.clientX < midX ? index : index + 1;
          // Adjust if moving forward (since removing shifts indices)
          if (fromIdx < toIdx) { toIdx--; }
          if (fromIdx === toIdx) { return; }
          // Reorder coverageValues
          const [moved] = coverageValues.splice(fromIdx, 1);
          coverageValues.splice(toIdx, 0, moved);
          // Also adjust replaceIndex if active
          if (replaceIndex !== null) {
            if (replaceIndex === fromIdx) {
              replaceIndex = toIdx;
            } else if (fromIdx < replaceIndex && toIdx >= replaceIndex) {
              replaceIndex--;
            } else if (fromIdx > replaceIndex && toIdx <= replaceIndex) {
              replaceIndex++;
            }
          }
          syncHiddenInput();
          renderPills();
        });

        const label = document.createElement('span');
        label.className = 'u-text_body';
        label.textContent = labelForValue(value);
        pill.appendChild(label);

        const replaceBtn = document.createElement('button');
        replaceBtn.type = 'button';
        if (isUnresolved) {
          replaceBtn.className = 'btn btn-danger btn-sm p-2 ml-3';
          replaceBtn.textContent = 'Link';
        } else {
          replaceBtn.className = 'btn btn-link btn-sm px-3 py-2 ml-2';
          replaceBtn.innerHTML = '<i class="fas fa-exchange-alt"></i>';
        }
        replaceBtn.addEventListener('click', () => setReplaceMode(index));
        pill.appendChild(replaceBtn);

        const removeBtn = document.createElement('button');
        removeBtn.type = 'button';
        removeBtn.className = 'btn btn-link btn-sm text-danger px-3 py-2 ml-2';
        removeBtn.innerHTML = '<i class="fas fa-trash "></i>';
        removeBtn.setAttribute('aria-label', 'Remove');
        removeBtn.addEventListener('click', () => {
          coverageValues.splice(index, 1);
          syncHiddenInput();
          renderPills();
        });
        pill.appendChild(removeBtn);

        pillsHolder.appendChild(pill);
      });

      refreshReplaceState();
    };

    const addToken = () => {
      const token = (addTokenInput.value || '').trim();
      if (!token) { return; }
      if (coverageValues.includes(token)) {
        addTokenInput.value = '';
        return;
      }
      coverageValues.push(token);
      syncHiddenInput();
      renderPills();
      addTokenInput.value = '';
    };

    const upsertVocabMeta = (item) => {
      const id = String(item.id);
      vocabMeta[id] = {
        label: item.display || item.title || item.slug || `Vocab #${id}`,
        tooltip: item.meaning || ''
      };
    };

    const addVocabByResult = (item) => {
      const asNumber = Number(item.id);
      if (!Number.isFinite(asNumber)) { return; }
      if (coverageValues.includes(asNumber)) { return; }
      upsertVocabMeta(item);
      coverageValues.push(asNumber);
      syncHiddenInput();
      renderPills();
    };

    const replaceWithResult = (item) => {
      if (replaceIndex === null) { return; }
      const asNumber = Number(item.id);
      if (!Number.isFinite(asNumber)) { return; }
      upsertVocabMeta(item);
      coverageValues.splice(replaceIndex, 1, asNumber);
      syncHiddenInput();
      renderPills();
      exitReplaceMode();
    };

    const renderSearchResults = (resultsEl, items, onSelect) => {
      resultsEl.innerHTML = '';
      if (!items.length) {
        const li = document.createElement('li');
        li.className = 'text-muted';
        li.textContent = 'No results';
        resultsEl.appendChild(li);
        return;
      }
      items.forEach((item) => {
        const li = document.createElement('li');
        li.className = 'py-1 px-1 u-border_b-light';
        li.style.cursor = 'pointer';
        const labelText = item.display || item.title || item.slug || `Vocab #${item.id}`;
        const strong = document.createElement('strong');
        strong.textContent = labelText;
        li.appendChild(strong);

        const meaning = (item.meaning || '').toString().trim();
        if (meaning.length) {
          const meaningEl = document.createElement('small');
          meaningEl.className = 'text-muted ml-1';
          meaningEl.textContent = meaning;
          li.appendChild(document.createTextNode(' '));
          li.appendChild(meaningEl);
        }

        li.addEventListener('click', () => onSelect(item));
        resultsEl.appendChild(li);
      });
    };

    const performSearch = (query, resultsEl, onSelect) => {
      const term = (query || '').trim();
      resultsEl.innerHTML = '';

      if (!searchUrl) {
        const li = document.createElement('li');
        li.className = 'text-danger';
        li.textContent = 'Search unavailable';
        resultsEl.appendChild(li);
        return;
      }

      if (term.length < 2) {
        if (term.length === 0) { return; }
        const li = document.createElement('li');
        li.className = 'text-muted';
        li.textContent = 'Type at least 2 characters';
        resultsEl.appendChild(li);
        return;
      }

      const loading = document.createElement('li');
      loading.className = 'text-muted';
      loading.textContent = 'Searching…';
      resultsEl.appendChild(loading);

      const fetchOptions = {
        method: 'POST',
        type: "script",
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          ...(csrfToken ? { 'X-CSRF-Token': csrfToken } : {})
        },
        body: JSON.stringify({ term })
      };

      fetch(searchUrl, fetchOptions)
        .then((response) => response.json())
        .then((data) => {
          renderSearchResults(resultsEl, Array.isArray(data) ? data : [], onSelect);
        })
        .catch(() => {
          resultsEl.innerHTML = '';
          const li = document.createElement('li');
          li.className = 'text-danger';
          li.textContent = 'Search failed';
          resultsEl.appendChild(li);
        });
    };

    addTokenButton.addEventListener('click', addToken);
    const preventFormSubmitOnInput = (inputEl) => {
      inputEl.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
          event.preventDefault();
        }
      });
    };
    const preventFormSubmitOnInputAdd = (inputEl) => {
      inputEl.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
          event.preventDefault();
          addTokenButton.click();
        }
      });
    };

    preventFormSubmitOnInputAdd(addTokenInput);

    addSearchInput.addEventListener('input', () => {
      clearTimeout(addSearchTimeout);
      addSearchTimeout = setTimeout(() => {
        performSearch(addSearchInput.value, addSearchResults, (item) => {
          addVocabByResult(item);
          addSearchInput.value = '';
          addSearchResults.innerHTML = '';
        });
      }, 500);
    });

    addSearchInput.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        clearTimeout(addSearchTimeout);
        performSearch(addSearchInput.value, addSearchResults, (item) => {
          addVocabByResult(item);
          addSearchInput.value = '';
          addSearchResults.innerHTML = '';
        });
      }
    });

    preventFormSubmitOnInput(addSearchInput);

    replaceSearchInput.addEventListener('input', () => {
      clearTimeout(replaceSearchTimeout);
      replaceSearchTimeout = setTimeout(() => {
        performSearch(replaceSearchInput.value, replaceSearchResults, (item) => {
          replaceWithResult(item);
          replaceSearchResults.innerHTML = '';
          replaceSearchInput.value = '';
        });
      }, 500);
    });

    replaceSearchInput.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        clearTimeout(replaceSearchTimeout);
        performSearch(replaceSearchInput.value, replaceSearchResults, (item) => {
          replaceWithResult(item);
          replaceSearchResults.innerHTML = '';
          replaceSearchInput.value = '';
        });
      }
    });

    preventFormSubmitOnInput(replaceSearchInput);

    replaceCancel.addEventListener('click', exitReplaceMode);

    // --- Run AI Generator (remote) ---
    const aiButton = container.querySelector('.js-run-ai-generator');
    const aiSpinner = container.querySelector('.loading-spinner');
    if (aiButton) {
      aiButton.addEventListener('click', () => {
        if (!confirm('Are you sure?')) { return; }
        const aiUrl = aiButton.dataset.aiUrl;
        if (!aiUrl) { return; }

        aiButton.disabled = true;
        if (aiSpinner) { aiSpinner.style.display = 'block'; }

        fetch(aiUrl, {
          method: 'GET',
          headers: {
            'Accept': 'application/json',
            ...(csrfToken ? { 'X-CSRF-Token': csrfToken } : {})
          }
        })
          .then((response) => {
            if (!response.ok) { throw new Error('AI service request failed'); }
            return response.json();
          })
          .then((data) => {
            // data is an object keyed by vocab id or string token
            // e.g. { "685": { id: 685, label: "本", tooltip: "book" }, "山本": { id: null, label: "山本", tooltip: "" } }
            let added = 0;
            Object.keys(data).forEach((key) => {
              const entry = data[key];
              if (entry.id != null && Number.isFinite(Number(entry.id))) {
                // Resolved vocab with a numeric ID
                const vocabId = Number(entry.id);
                // Skip duplicates already in coverageValues
                if (coverageValues.includes(vocabId)) { return; }
                // Merge into vocabMeta
                vocabMeta[String(vocabId)] = {
                  label: entry.label || `Vocab #${vocabId}`,
                  tooltip: entry.tooltip || ''
                };
                coverageValues.push(vocabId);
                added++;
              } else {
                // Unresolved token (no vocab match) — add as string
                const token = entry.label || key;
                if (coverageValues.includes(token)) { return; }
                coverageValues.push(token);
                added++;
              }
            });
            syncHiddenInput();
            renderPills();
            alert(`AI Generator complete. ${added} new vocab added, ${Object.keys(data).length - added} duplicates skipped.`);
          })
          .catch((err) => {
            console.error('AI Generator error:', err);
            alert('AI Generator failed. Check the console for details.');
          })
          .finally(() => {
            aiButton.disabled = false;
            if (aiSpinner) { aiSpinner.style.display = 'none'; }
          });
      });
    }

    renderPills();
    console.log("test")
  }
});
