      // Fixes the initial duration bug in BB OS7, where the media.duration is infinity and displays as NaN:NaN due to Date() using inifity.
      if (isFinite(media.duration)) {
        this.status.duration = media.duration;
      }

      ct = media.currentTime;
      cpa = this.status.duration > 0 ? (100 * ct) / this.status.duration : 0;
      if (typeof media.seekable === "object" && media.seekable.length > 0) {
        sp =
          this.status.duration > 0
            ? (100 * media.seekable.end(media.seekable.length - 1)) /
              this.status.duration
            : 100;
        cpr =
          this.status.duration > 0
            ? (100 * media.currentTime) /
              media.seekable.end(media.seekable.length - 1)
            : 0; // Duration conditional for iOS duration bug. ie., seekable.end is a NaN in that case.
      } else {
        sp = 100;
        cpr = cpa;
      }

      if (override) {
        ct = 0;
        cpr = 0;
        cpa = 0;
      }

      this.status.seekPercent = sp;
      this.status.currentPercentRelative = cpr;
      this.status.currentPercentAbsolute = cpa;
      this.status.currentTime = ct;

      this.status.remaining = this.status.duration - this.status.currentTime;

      this.status.videoWidth = media.videoWidth;
      this.status.videoHeight = media.videoHeight;

      this.status.readyState = media.readyState;
      this.status.networkState = media.networkState;
      this.status.playbackRate = media.playbackRate;
      this.status.ended = media.ended;
