    function load_tab(tab) {
      return $.ajax({
        type: "GET",
        url: "/cram/load_tab/" + tab,
        dataType: "script",
      });
    }

    function load_deck(deck) {
      var tab = $(".content-to-cram .nav-item.active .nav-link").attr("id");
      return $.ajax({
        type: "GET",
        url: "/cram/load_deck/" + deck + "/" + tab,
        dataType: "script",
      });
    }

