// used in /grammar_points/_audio_upload_buttons, /vocabs/_audio_upload_buttons, and /example_sentences/_audio_upload_buttons
function directUploadSetup() {
  $(".directUpload input:file").each(function (i, elem) {
    var fileInput = $(elem);
    var form = $(fileInput.parents("form:first"));
    var submitButton = form.find('input[type="submit"]');
    var progressBar = $("<div class='bar'></div>").appendTo(form);
    var barContainer = $("<div class='progress'></div>").append(progressBar);

    fileInput.after(barContainer);
    fileInput.fileupload({
      fileInput: fileInput,
      url: form.data("url"),
      type: "POST",
      autoUpload: false,
      dropZone: $(this),
      formData: form.data("form-data"),
      paramName: "file", // S3 does not like nested name fields i.e. name="user[avatar_url]"
      dataType: "XML", // S3 returns XML if success_action_status is set to 201
      replaceFileInput: false,
      add: function (e, data) {
        data.submit();
      },
      progressall: function (e, data) {
        var progress = parseInt((data.loaded / data.total) * 100, 10);
        progressBar.css("width", progress + "%");
      },
      start: function (e) {
        submitButton.prop("disabled", true);

        progressBar
          .css("background", example_sentences_accent)
          .css("display", "block")
          .css("width", "0%")
          .text("Loading...");
      },
      done: function (e, data) {
        submitButton.prop("disabled", false);
        progressBar.text(I18n.t("js.example_sentences.uploading_done"));

        // extract key and generate URL from response
        var key = $(data.jqXHR.responseXML).find("Key").text();
        var url = "https://dk3kgylsgq3k1.cloudfront.net/" + key;

        fileInput.parent().find($(".placeholder")).remove();

        if ($("#user_id").length >= 1) {
          fileInput
            .parent()
            .find($(".image-preview"))
            .html(
              "<img src='" +
                url +
                "' style='width: 200px;height: 200px;object-fit: cover;border-radius: 50%;'/>"
            );
        } else if ($("#course_id").length >= 1) {
          fileInput
            .parent()
            .find($(".image-preview"))
            .html(
              "<img src='" +
                url +
                "' style='width: 352px;height: 200px;object-fit: cover;'/>"
            );
        }

        fileInput
          .parent()
          .find($(".filename"))
          .html(
            key.split("/").pop() +
              "<br>" +
              I18n.t("js.example_sentences.has_been_uploaded")
          );
        fileInput.parent().find($(".filename")).css("display", "none");

        // create hidden field
        if ($("#s3_image").length == 0) {
          var input = $("<input />", {
            type: "hidden",
            name: fileInput.attr("name"),
            value: url,
            id: "s3_image",
          });

          form.append(input);
        } else {
          $("#s3_image").val(url);
        }

        $.ajax({
          method: "POST",
          url: "/audio_upload",
          data: {
            url: url,
            study_question_id: $(form.find(".sq_form_id")).val(),
            sex: form.hasClass("female_audio") ? "female" : "male",
          },
        });
      },
      fail: function (e, data) {
        submitButton.prop("disabled", false);
        progressBar
          .css("background", example_sentences_red)
          .text(I18n.t("js.example_sentences.failed"));
      },
    });
  });
}

document.addEventListener("turbolinks:load", function () {
  // Sets furigana on the admin edit forms

  $(".js_admin--example").JVFurigana();

  var urlClipboard = new ClipboardJS(".js_copy-url-btn");

  urlClipboard.on("success", function (e) {
    $(".copied-success").show();

    setTimeout(function (event) {
      $(".copied-success").hide();
    }, 1000);
  });

  // .directUpload used in /grammar_points/_audio_upload_buttons, /vocabs/_audio_upload_buttons, /example_sentences/_audio_upload_buttons
  if ($(".directUpload").length >= 1) {
    // For image upload //
    directUploadSetup();
    $(document).on("dragover", ".audio-dropzone", function () {
      $(this).addClass("js_audio-dropzone--dragover");
    });

    $(document).on("drop", ".audio-dropzone", function () {
      $(this).addClass("js_audio-dropzone--drop");
    });

    $(document).on("dragleave", ".audio-dropzone", function () {
      $(this).addClass("js_audio-dropzone--drop");
    });

    $(document).on("click", ".js_remove-audio", function (event) {
      $(this)
        .closest(".audio_upload-container")
        .find(".audio-dropzone")
        .removeClass("u-hidden");
      $(this).parent().remove();
    });
  }
});
document.addEventListener("turbolinks:load", function () {
  // These are variables for hard-coded values.
  if ($("body").hasClass("theme-modern-dark")) {
    var feedback_red = "rgba(224, 54, 54, 1)"; // general_error
  } else {
    var feedback_red = "rgba(232, 41, 53, 1)";
  }
  // End hard-coded values variables

  if ($(".js_feedback-spacing").length >= 1) {
    $(".feedback-japanese").JVFurigana();
  }

  $("body").on("click", ".js-reply--update-button", function (event) {
    var message = $(this).parent().find(".reply_content");
    if (message.val() == "") {
      event.preventDefault();
      message.css("border", "0.063em solid " + feedback_red);
      if (message.parent().find(".selfstudy-warning").length == 0) {
        message
          .parent()
          .append(
            $(
              "<div class='selfstudy-warning'>" +
                I18n.t("js.feedback.message_blank") +
                "</div>"
            )
          );
      }
    }
  });
  $("body").on("click", ".close-feedback", function (event) {
    $($(this).parent().parent().parent().find(".show-bug-report-form")).show();
    $(this).parent().parent().parent().hide();
  });

  $("body").on("click", ".js_show-feedback-reply-form", function () {
    $(this).parent().find(".js_feedback-reply").show();
    $(this).parent().find(".js_feedback-reply .reply_content").focus();
    $(this).hide();
  });

  $("body").on("click", ".js_feedback-reply .close-feedback", function (event) {
    $(this)
      .parent()
      .parent()
      .parent()
      .parent()
      .find(".js_show-feedback-reply-form")
      .show();
  });

  $("body").on("click", ".show--reply-edit-form", function (event) {
    if ($(this).html() == I18n.t("js.feedback.edit")) {
      $(this).html(I18n.t("js.feedback.close"));
    } else {
      $(this).html(I18n.t("js.feedback.edit"));
    }
    $(this).parent().find(".edit_reply").toggle();
    $(this).parent().find(".edit_reply textarea").focus();
  });

  // Status
  $("body").on("change", ".js-feedback-update-status", function (event) {
    var status = $(this).val();
    if (!status) return;
    $.ajax({
      type: "POST",
      url: "/feedback/update_status",
      data: {
        id: $(this).closest(".js_feedback").attr("id").split("_")[1],
        status: status,
      },
    });
  });

  // Source
  $("body").on("change", ".js-feedback-update-source", function (event) {
    var source = $(this).val();
    if (!source) return;
    $.ajax({
      type: "POST",
      url: "/feedback/update_source",
      data: {
        id: $(this).closest(".js_feedback").attr("id").split("_")[1],
        source: source,
      },
    });
  });

  // Language
  $("body").on("change", ".js-feedback-update-language", function (event) {
    var language = $(this).val();
    if (!language) return;
    $.ajax({
      type: "POST",
      url: "/feedback/update_language",
      data: {
        id: $(this).closest(".js_feedback").attr("id").split("_")[1],
        language: language,
      },
    });
  });

  // Like Toggle
  $("body").on("click", ".reply-like-button.clickable", function (event) {
    $.ajax({
      type: "POST",
      url: "/replies/update_liked_status",
      data: {
        id: $(this).attr("id").split("_")[1],
      },
    });
  });

  if ($("#contact-feedback").length >= 1) {
    function getFeedbackForm(source) {
      $.ajax({
        method: "POST",
        url: "/get_feedback_form",
        dataType: "script",
        data: {
          source: source,
          topic: {
            topic: $(".feedback-tile.active").data("topic"),
            message: $(".feedback-tile.active").data("topic-human"),
          },
          reason: {
            reason: $(".reason-tile.active").data("reason"),
            message: $(".reason-tile.active").data("reason-human"),
          },
        },
      });
    }

    $(".feedback-tile").on("click", function (event) {
      $(".feedback-tile.active").removeClass("active");
      $(this).addClass("active");
      if ($($(this).data("target")).length == 0) {
        $(".reason-tile.active").removeClass("active");
        $(".tab-pane.active").removeClass("active");
        getFeedbackForm("contact");
      }
    });
    $(".reason-tile").on("click", function (event) {
      if ($(this).hasClass("active")) {
        $("#feedbackForm").modal("show");
      } else {
        $(".reason-tile.active").removeClass("active");
        $(this).addClass("active");
        getFeedbackForm("contact");
      }
    });
  }

  $(".show-bug-report-form").on("click", function (event) {
    if ($(this).hasClass("form-loaded")) {
      event.preventDefault();
      event.stopImmediatePropagation();
      $("#feedbackForm").modal("show");
    } else {
      $(".show-bug-report-form.form-loaded").removeClass("form-loaded");
      $(this).addClass("form-loaded");
    }
  });

  $(document).on("click", ".inline-reason-tile", function (event) {
    if (!$("#report-form-details").is(":visible")) {
      $("#report-form-details").removeClass("u-hidden");
      $("#report-form-details").addClass("u-block");
    }
    $(".inline-reason-tile.active").removeClass("active");
    $(this).addClass("active");
    $(".feedback-prompt").html(I18n.t("js.feedback.send_message") + ".");
    $(".form-reason").html($(this).data("reason-human"));
    $("#reason").val($(this).data("reason"));
  });
});
