// Admin-only TTS buttons for StudyQuestion edit page
(function() {
  // Add spinner animation CSS if not already present
  if (!document.getElementById('tts-spinner-style')) {
    var style = document.createElement('style');
    style.id = 'tts-spinner-style';
    style.textContent = '@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }';
    document.head.appendChild(style);
  }

  function csrfToken() {
    var meta = document.querySelector('meta[name="csrf-token"]');
    return meta ? meta.getAttribute('content') : null;
  }

  function getStudyQuestionId() {
    var el = document.querySelector('input.sq_form_id');
    if (el && el.value) return el.value;
    var m = window.location.pathname.match(/study_questions\/(\d+)/);
    return m ? m[1] : null;
  }

  function setupSpeedPresets() {
    document.querySelectorAll('.tts-speed-preset').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        var speed = this.dataset.speed;
        var input = document.getElementById('tts_speed_sq');
        if (input) input.value = speed;
      });
    });
  }

  function ensureButtons() {
    var wrapper = document.querySelector('.sq_wrapper--audio');
    if (!wrapper) return;
    if (wrapper.querySelector('.tts-generate-buttons')) return;

    setupSpeedPresets();

    var container = document.createElement('div');
    container.className = 'tts-generate-buttons u-flex u-gap_8';

    var btnFemale = document.createElement('button');
    btnFemale.type = 'button';
    btnFemale.className = 'v-button_default u-button_hollow--accent-primary tts-generate-button';
    btnFemale.dataset.sex = 'female';
    btnFemale.textContent = 'Generate (Female)';

    var btnMale = document.createElement('button');
    btnMale.type = 'button';
    btnMale.className = 'v-button_default u-button_hollow--accent-primary tts-generate-button';
    btnMale.dataset.sex = 'male';
    btnMale.textContent = 'Generate (Male)';

    container.appendChild(btnFemale);
    container.appendChild(btnMale);
    wrapper.prepend(container);

    container.addEventListener('click', function(e) {
      var target = e.target;
      if (!(target && target.classList.contains('tts-generate-button'))) return;
      var id = getStudyQuestionId();
      if (!id) { alert('Missing Study Question ID'); return; }
      var sex = target.dataset.sex || 'female';

      // Read current Audio String (for confirm text and payload)
      var input = document.getElementById('tts_audio_text_sq') || document.querySelector('.tts-audio-text');
      var audioText = input ? (input.value || '') : '';
      var shortText = (audioText || '').trim();
      if (shortText.length > 80) shortText = shortText.slice(0, 80) + '…';

      // Confirm to prevent misclicks, include Audio String if available
      var msg = 'Generate TTS (' + (sex === 'male' ? 'Male' : 'Female') + ')';
      msg += shortText ? (' for "' + shortText + '"?') : ' for this Vocab Study Question?';
      var ok = window.confirm(msg);
      if (!ok) return;

      // disable all TTS buttons
      var all = container.querySelectorAll('.tts-generate-button');
      all.forEach(function(b){ b.disabled = true; b.classList.add('u-disabled'); });

      // show in-progress indicator
      var $wrapper = $('.sq_wrapper--audio');
      $wrapper.find('.tts-progress').remove();
      var $btns = $wrapper.find('.tts-generate-buttons').first();
      var $progress = $('<div class="tts-progress u-text_fg-secondary" style="margin-left:8px; display: flex; align-items: center; gap: 8px;"></div>');
      $progress.html('<div class="spinner" style="border: 2px solid #f3f3f3; border-top: 2px solid #555; border-radius: 50%; width: 16px; height: 16px; animation: spin 1s linear infinite;"></div> Generating TTS ' + (sex === 'male' ? '(Male)' : '(Female)') + (shortText ? (' for "' + shortText + '"...') : '...'));
      if ($btns.length) { $btns.append($progress); } else { $wrapper.prepend($progress); }

      // Build audio_text (trim to ~1000 chars for provider limits)
      var audioTextToSend = audioText;
      if (audioTextToSend && audioTextToSend.length > 1000) {
        audioTextToSend = audioTextToSend.slice(0, 1000);
      }

      // Read speed value
      var speedInput = document.getElementById('tts_speed_sq');
      var voiceSpeed = speedInput ? speedInput.value : '0.9';

      // ajax request expecting a JS response
      $.ajax({
        url: '/tts/generate',
        method: 'POST',
        dataType: 'script',
        headers: { 'X-CSRF-Token': csrfToken() },
        data: { study_question_id: id, sex: sex, audio_text: audioTextToSend, voice_speed: voiceSpeed },
        error: function(xhr, status, error) {
          // Remove spinner on error
          var $wrapper = $('.sq_wrapper--audio');
          $wrapper.find('.tts-progress').remove();
          
          // Show error message
          var errorMsg = 'TTS generation failed';
          if (xhr.responseText) {
            try {
              var json = JSON.parse(xhr.responseText);
              if (json && json.error) errorMsg = json.error;
            } catch(e) {
              errorMsg = 'TTS generation failed: ' + status;
            }
          }
          alert(errorMsg);
          
          // Re-enable buttons
          var all = container.querySelectorAll('.tts-generate-button');
          all.forEach(function(b){ b.disabled = false; b.classList.remove('u-disabled'); });
        }
      });
    });
  }

  document.addEventListener('turbolinks:load', ensureButtons);
})();
