  // On <checkbox> (slider) update, sets the values, flashes the loading spinner, and submits the form.
  $(document).on("click", ".js_u-set_toggle", function () {
    var input = $($(this).parent().find("input[type=checkbox]"));
    var hiddenInput = $($(this).parent().find("input[type=hidden]"));
    if (input.val() == "Off") {
      input.val("On");
      hiddenInput.val("On");
    } else if (input.val() == "On") {
      input.val("Off");
      hiddenInput.val("Off");
    } else if (input.val() == "true") {
      input.val("false");
      hiddenInput.val("false");
    } else if (input.val() == "false") {
      input.val("true");
      hiddenInput.val("true");
    }

    $(this).parent().parent().next().show();
    $(this).closest(".js_u-set_form").trigger("submit");

    setTimeout(() => {
      $(this).parent().parent().next().hide();
    }, 600);
  });

  // Updates the user display language and sets the cookie
  const $languageSelect = $("#js_u-set_language");

  $languageSelect.data("previous-language", $languageSelect.val());

  var prevLang = $languageSelect.val();

  $languageSelect.on("change", function (event) {
    const selectedLanguage = $(this).val();
    const previousLanguage = $(this).data("previous-language");

    if (selectedLanguage === "spanish" && previousLanguage !== "spanish") {
      // $(this).trigger("change.confirm");
      $("#langWarningSpanish").modal("show");
      event.preventDefault();
      event.stopPropagation();
    } else if (selectedLanguage === "french" && previousLanguage !== "french") {
      // $(this).trigger("change.confirm");
      $("#langWarningFrench").modal("show");
      event.preventDefault();
      event.stopPropagation();
    } else if (
      selectedLanguage === "indonesian" &&
      previousLanguage !== "indonesian"
    ) {
      // $(this).trigger("change.confirm");
      $("#langWarningIndonesian").modal("show");
      event.preventDefault();
      event.stopPropagation();
    } else if (selectedLanguage != previousLanguage) {
      if ($(this).hasClass("js_u-set_locale")) {
        $.ajax({
          method: "POST",
          url: "/users/set_language",
          data: { locale: selectedLanguage },
        });
      } else {
        window.location.reload();
      }
    }
  });

  $(".confirm-lang-warn").on("click", function (event) {
    $.ajax({
      method: "POST",
      url: "/users/set_language",
      data: { locale: $languageSelect.val() },
    });
  });

  $(".cancel-lang-warning").on("click", function (event) {
    $languageSelect.val($languageSelect.data("previous-language"));
  });

  // Combine both event listeners to ensure both checks are performed
  $languageSelect.on("change", function (event) {
    // Call the original and confirmation listeners
    $(this).trigger("change.confirm"); // First, handle confirmation
    $(this).trigger("change.original"); // Then, perform the original action
  });

