/**
 * @param {string} selector - the last bit of the section class, ex: for 'js_u-set_name', you'd use 'name'
 */
const toggleInlineSettingsForm = (selector) => {
  const textBlock = document.querySelector(`.js_u-set_${selector}`);
  const form = document.querySelector(`.js_u-set_${selector}-form`);

  if (!form) return;

  if (form.classList.contains("u-hidden")) {
    textBlock.classList.remove("u-flex");
    textBlock.classList.add("u-hidden");
    form.classList.remove("u-hidden");
    form.classList.add("u-grid");
  } else {
    textBlock.classList.remove("u-hidden");
    textBlock.classList.add("u-flex");
    form.classList.remove("u-grid");
    form.classList.add("u-hidden");
  }
};

/**
 * Shows then hides the loading spinner and hides the inline form after submission
 * @param {string} selector - provided via 'hideInlineSettingsForm()'
 */
const flashLoadingSpinner = (selector) => {
  const spinner = document.querySelector(
    `.js_u-set_${selector}-spinner .loading-spinner`
  );
  spinner.style.display = "block";

  setTimeout(() => {
    spinner.style.display = "none";
    toggleInlineSettingsForm(selector);
  }, 600);
};
document.addEventListener("turbolinks:load", function () {
  function enterVacationMode() {
    $.ajax({
      type: "POST",
      url: "/settings/toggle_vacation_mode",
      dataType: "script",
    });
  }

  function get_elapsed_time_string(total_seconds) {
    function pretty_time_string(num) {
      return (num < 10 ? "0" : "") + num;
    }

    var minutes = Math.floor(total_seconds / 60);
    total_seconds = total_seconds % 60;

    var seconds = Math.floor(total_seconds);

    // Pad the minutes and seconds with leading zeros, if required
    minutes = pretty_time_string(minutes);
    seconds = pretty_time_string(seconds);

    // Compose the string for display
    var currentTimeString = minutes + ":" + seconds;

    return currentTimeString;
  }

  var elapsed_seconds = 0;
  var est_time = $(".vm-time").data("timeInSecs");
  var timerInterval = setInterval(function () {
    elapsed_seconds = elapsed_seconds + 1;
    $(".vm-timer").html(get_elapsed_time_string(elapsed_seconds));
    if (elapsed_seconds > 5) {
      if (elapsed_seconds < est_time) {
        if (elapsed_seconds < est_time / 2) {
          $(".vm-status").html("On Track! 🙂");
        } else {
          $(".vm-status").html("Getting Close! 😀");
        }
      } else {
        $(".vm-status").html("Sorry! It's taking longer than expected. 😳");
      }
    } else {
      $(".vm-status").html("");
    }
  }, 1000);
  clearInterval(timerInterval);

  function sendVactionModeRequest() {
    $.ajax({
      type: "POST",
      url: "/settings/batch_process_vacation_mode",
      dataType: "json",
      success: function (response) {
        $(".vm-processed-count").html(response["processed"]);
        if (response["total"] == 0) {
          $(".vm-percent").html("100.0");
        } else {
          $(".vm-percent").html(
            ((100.0 * response["processed"]) / response["total"]).toFixed(1)
          );
        }
        if (response["total"] == response["processed"]) {
          // Remove navigation prompt
          $(window).off("beforeunload");
          clearInterval(timerInterval);
          $(".vm-status").html("All Done!");
          $(".js-processing-warning").hide();
          $(".import-status").find(".loading-spinner").hide();
        } else {
          sendVactionModeRequest();
        }
      },
    });
  }

  $(document).on("click", ".js_vacation_toggle", function (e) {
    if ($(this).hasClass("disable-vacation-mode")) {
      e.preventDefault();
      e.stopImmediatePropagation();
      $(".js-vacation-status").css("display", "flex");
      $(".vm-form-warnings").hide();
      $(".import-status").find(".loading-spinner").show();
      $(window).on("beforeunload", function (x) {
        return (x.originalEvent.returnValue =
          "Your vacation mode is still processing. Leaving now will interupt it. Continue?");
      });
      sendVactionModeRequest();
      // timerInterval();
    } else {
      enterVacationMode();
    }
  });
});
document.addEventListener("turbolinks:load", function () {
  if ($("#matome").length >= 1) {
    function recapSetup() {
      var slider = function (sliderElement) {
        var pages = [];
        var currentSlide = 1;
        var isChanging = false;
        var keyUp = { 38: 1, 33: 1 };
        var keyDown = { 40: 1, 34: 1 };

        var init = function () {
          setTimeout(function (_) {
            document.body.classList.add("slider__body");
            // control scrolling
            whatWheel =
              "onwheel" in document.createElement("div")
                ? "wheel"
                : document.onmousewheel !== undefined
                ? "mousewheel"
                : "DOMMouseScroll";
            window.addEventListener(whatWheel, function (e) {
              var direction = e.wheelDelta || e.deltaY;
              if (direction > 0) {
                changeSlide(-1);
              } else {
                changeSlide(1);
              }
            });

            window.addEventListener("touchmove", function (e) {
              var currentY = e.originalEvent.touches[0].clientY;
              if (currentY > lastY) {
                changeSlide(1);
              } else if (currentY < lastY) {
                changeSlide(-1);
              }
            });

            // allow keyboard input
            window.addEventListener("keydown", function (e) {
              if (keyUp[e.keyCode]) {
                changeSlide(-1);
              } else if (keyDown[e.keyCode]) {
                changeSlide(1);
              }
            });

            // page change animation is done
            detectChangeEnd() &&
              document
                .querySelector(sliderElement)
                .addEventListener(detectChangeEnd(), function () {
                  if (isChanging) {
                    setTimeout(function () {
                      isChanging = false;
                      // window.location.hash = document.querySelector('[data-slider-index="' + currentSlide + '"]').id;
                    }, 400);
                  }
                });

            // set up page and build visual indicators
            document
              .querySelector(sliderElement)
              .classList.add("slider__container");
            var indicatorContainer = document.createElement("div");
            indicatorContainer.classList.add("slider__indicators");

            var index = 1;
            [].forEach.call(
              document.querySelectorAll(sliderElement + " > *"),
              function (section) {
                var indicator = document.createElement("a");
                indicator.classList.add("slider__indicator");
                indicator.setAttribute("data-slider-target-index", index);
                indicatorContainer.appendChild(indicator);

                section.classList.add("slider__page");
                pages.push(section);
                section.setAttribute("data-slider-index", index++);
              }
            );

            document.body.appendChild(indicatorContainer);
            document
              .querySelector(
                'a[data-slider-target-index = "' + currentSlide + '"]'
              )
              .classList.add("slider__indicator--active");

            // stuff for touch devices
            var touchStartPos = 0;
            var touchStopPos = 0;
            var touchMinLength = 30;
            document.addEventListener("touchstart", function (e) {
              e.preventDefault();
              if (
                e.type == "touchstart" ||
                e.type == "touchmove" ||
                e.type == "touchend" ||
                e.type == "touchcancel"
              ) {
                var touch = e.touches[0] || e.changedTouches[0];
                touchStartPos = touch.pageY;
              }
            });
            document.addEventListener("touchend", function (e) {
              e.preventDefault();
              if (
                e.type == "touchstart" ||
                e.type == "touchmove" ||
                e.type == "touchend" ||
                e.type == "touchcancel"
              ) {
                var touch = e.touches[0] || e.changedTouches[0];
                touchStopPos = touch.pageY;
              }
              if (touchStartPos + touchMinLength < touchStopPos) {
                changeSlide(-1);
              } else if (touchStartPos > touchStopPos + touchMinLength) {
                changeSlide(1);
              }
            });
            $(".loading-spinner--holder").fadeOut("slow", this.remove);
          }, 1500);
        };

        // prevent double scrolling
        var detectChangeEnd = function () {
          var transition;
          var e = document.createElement("foobar");
          var transitions = {
            transition: "transitionend",
            OTransition: "oTransitionEnd",
            MozTransition: "transitionend",
            WebkitTransition: "webkitTransitionEnd",
          };

          for (transition in transitions) {
            if (e.style[transition] !== undefined) {
              return transitions[transition];
            }
          }
          return true;
        };

        // handle css change
        var changeCss = function (obj, styles) {
          for (var _style in styles) {
            if (obj.style[_style] !== undefined) {
              obj.style[_style] = styles[_style];
            }
          }
        };

        // handle page/section change
        var changeSlide = function (direction) {
          // already doing it or last/first page, staph plz
          if (
            isChanging ||
            (direction == 1 && currentSlide == pages.length) ||
            (direction == -1 && currentSlide == 1)
          ) {
            return;
          }

          // change page
          currentSlide += direction;
          isChanging = true;
          changeCss(document.querySelector(sliderElement), {
            transform: "translate3d(0, " + -(currentSlide - 1) * 100 + "%, 0)",
          });

          // change dots
          document
            .querySelector("a.slider__indicator--active")
            .classList.remove("slider__indicator--active");
          document
            .querySelector('a[data-slider-target-index="' + currentSlide + '"]')
            .classList.add("slider__indicator--active");
          if (
            $(".slider__indicator.slider__indicator--active").next().length == 0
          ) {
            $("#next_page_btn").addClass("last_page");
          } else {
            $("#next_page_btn").removeClass("last_page");
          }
        };

        // go to spesific slide if it exists
        var gotoSlide = function (where) {
          var target = document
            .querySelector(where)
            .getAttribute("data-slider-index");
          if (target != currentSlide && document.querySelector(where)) {
            changeSlide(target - currentSlide);
          }
        };

        // if page is loaded with hash, go to slide
        if (location.hash) {
          setTimeout(function () {
            window.scrollTo(0, 0);
            gotoSlide(location.hash);
          }, 1);
        }

        // we have lift off
        if (document.readyState === "complete") {
          init();
        } else {
          window.addEventListener("onload", init(), false);
        }

        // expose gotoSlide function
        return {
          gotoSlide: gotoSlide,
        };
      };
      var mySlider = slider(".slides");

      $(document).on("click", ".slider__indicator", function (e) {
        mySlider.gotoSlide(
          "#" +
            $(
              '[data-slider-index="' +
                $(this).data("slider-target-index") +
                '"]'
            ).attr("id")
        );
      });
      $("#next_page_btn").on("click", function (event) {
        mySlider.gotoSlide(
          "#" +
            $(
              '[data-slider-index="' +
                $(".slider__indicator.slider__indicator--active")
                  .next()
                  .data("slider-target-index") +
                '"]'
            ).attr("id")
        );
      });
      $(document).on("touchstart", ".slider__indicator", function (e) {
        mySlider.gotoSlide(
          "#" +
            $(
              '[data-slider-index="' +
                $(this).data("slider-target-index") +
                '"]'
            ).attr("id")
        );
      });
      $("#next_page_btn").on("touchstart", function (event) {
        mySlider.gotoSlide(
          "#" +
            $(
              '[data-slider-index="' +
                $(".slider__indicator.slider__indicator--active")
                  .next()
                  .data("slider-target-index") +
                '"]'
            ).attr("id")
        );
      });
    }
    if ($("#calculating-recap").length >= 1) {
      $.ajax({
        type: "GET",
        url: "recap/calc",
        dataType: "script",
        success: function (e) {
          recapSetup();
        },
      });
    } else {
      recapSetup();
    }
  }

  // Shows confirmation text on profile reset page
  $("#js_reset-confirmation").on("click", function (event) {
    if ($("#review_target").val()) {
      var result = confirm(I18n.t("js.custom.delete_reviews_confirmation"));

      if (!result) {
        event.preventDefault();
      }
    }
  });

  // copied from user_settings.js
  // show loading spinner when generate api button clicked
  $(document).on("click", ".regenerate-api-token", function (event) {
    $(this).next().show();
  });
});
