document.addEventListener("turbolinks:load", function () {
  // This sets the furigana based on the 'temp_furigana' setting
  // Takes the element (as a string with # or. , ex: ".vocab-tile--title")
  //           furigana variable(as a string with # or., ex: ".temp_furigana")
  //           furigana data(as a string(ex: "furigana") as inputs
  // * used window.functionName to make it a global function - might be a better way, but that's for a later project.
  window.furiganaHelper = function (element, furiganaVariable, furiganaData) {
    var furiganaSetting = $(furiganaVariable).data(furiganaData)
    if (furiganaSetting == "Off") {
      $(element).JVFuriganaOff()
    } else if (furiganaSetting == "Wanikani") {
      $(element).JVFuriganaWanikani()
    } else {
      $(element).JVFurigana()
    }
  }
});
