document.addEventListener("turbolinks:load", function () {
  $(document).on("click", ".js_wani_kani_toggle", function () {
    var $toggle = $(this);
    var $checkbox = $toggle.siblings("input[type=checkbox]");
    var $hiddenInput = $toggle.siblings("input[type=hidden]");
    var $spinner = $toggle
      .closest(".js_wani_kani_form")
      .find(".loading-spinner");
    var $checkmark = $toggle.closest(".js_wani_kani_form").find(".fa-check");

    var newState = !$checkbox.is(":checked");
    $checkbox.prop("checked", newState);
    $hiddenInput.val(newState ? "true" : "false");

    $checkmark.hide();
    $spinner.show();

    var $form = $toggle.closest(".js_wani_kani_form");

    $.ajax({
      url: $form.attr("action"),
      method: $form.attr("method"),
      data: $form.serialize(),
      success: function (response) {
        if (newState) {
          $checkbox.prop("checked", true);
          $hiddenInput.val("true");
        } else {
          $checkbox.prop("checked", false);
          $hiddenInput.val("false");
        }
        $spinner.hide();
        $checkmark.show();
      },
    });
  });

  $(document).on("click", ".js_u-set_wanikani-sync", function () {
    var $container = $(this).closest(".u-flex");
    var $button = $(this);
    $button.hide();

    $container.find(".loading-spinner").show();

    $container.find(".last-import").hide();
    $container.find(".import-status").show();

    $container.closest(".u-flex_column").find(".being-processed").show();
    $container.closest(".u-flex_column").find(".import-warning").hide();

    setTimeout(function () {
      $container.find(".loading-spinner").hide();
    }, 5000);
  });

  $("#wani_kani_connect").on("hidden.bs.modal", function () {
    location.reload();
  });

  $("#wani_kani_connect").on("shown.bs.modal", function () {
    $(".js_wanikani_sync_settings select").trigger("change");
  });

  $(".js_wanikani_sync_settings select").on("change", function (event) {
    event.preventDefault();

    $(this).closest(".js_wanikani_sync_settings").submit();

    const selectedValue = $(this).val();

    $(".default_desc, .practice_desc, .mastered_desc").hide();

    if (selectedValue === "default") {
      $(".default_desc").show();
    } else if (selectedValue === "practice") {
      $(".practice_desc").show();
    } else if (selectedValue === "mastered") {
      $(".mastered_desc").show();
    }
  });

  $(document)
    .on("ajax:beforeSend", "form", function () {
      $(this).find(".loading-spinner").show();
      $(this).find("#api-key-warning").hide();
    })
    .on("ajax:complete", "form", function () {
      $(this).find(".loading-spinner").hide();
    });
});
